import textwrap

import matplotlib.pyplot as plt
import pandas as pd

import config


METRICS = {'popular': 'Most popular', 'attended': 'Most attended',
           'best_rated': 'Best rated', 'feedbacked': 'Most feedbacked'}
METRIC_SQL = {
    'popular': ("i.status IN ('confirmed','attended','not_attended')", 'COUNT(*)', 'COUNT(*)'),
    'attended': ("i.status='attended'", 'COUNT(*)', 'COUNT(*)'),
    'best_rated': ('i.rating IS NOT NULL', 'AVG(i.rating)', 'COUNT(i.rating)'),
    'feedbacked': ('i.rating IS NOT NULL', 'COUNT(i.rating)', 'COUNT(i.rating)'),
}
FILTER_SQL = {'you': ' AND i.user_id=?', 'all': '',
              'direction': ' AND d.key=?', 'bundle': ' AND b.key=?'}
RATING_MINIMUMS = {'you': config.MIN_RATINGS_YOU, 'all': config.MIN_RATINGS_ALL_USERS}


def get_ranking(connection, metric, scope, user_id, direction_key=None, bundle_key=None,
                top_n=config.RANKING_TOP_N):
    """Return series-level statistics using fixed SQL fragments and bound filter values.

    :param connection: open SQLite connection
    :param metric: one of METRICS
    :param scope: 'you' for the supplied user, or 'all' for anonymous aggregates
    :param user_id: local user ID; ignored for scope 'all'
    :param direction_key: optional direction filter
    :param bundle_key: optional bundle filter, combined with direction using AND
    :param top_n: positive integer result limit
    :return: DataFrame indexed by series ID, never containing user names or IDs
    """
    if metric not in METRICS or scope not in RATING_MINIMUMS:
        raise ValueError('Choose a known ranking metric and scope.')
    if type(top_n) is not int or top_n <= 0:
        raise ValueError('Ranking limit must be a positive integer.')
    if scope == 'you' and (type(user_id) is not int or user_id <= 0):
        raise ValueError('Your ranking requires a positive user ID.')
    condition, value, count = METRIC_SQL[metric]
    parts = ['SELECT s.id,s.title,s.organizer,d.key AS direction_key,b.name AS bundle_name,',
             value, ' AS value,', count, ' AS n FROM interactions i',
             ' JOIN events e ON e.id=i.event_id JOIN series s ON s.id=e.series_id',
             ' JOIN bundles b ON b.id=s.bundle_id JOIN directions d ON d.id=b.direction_id',
             ' WHERE ', condition, FILTER_SQL[scope]]
    params = [user_id] if scope == 'you' else []
    _append_filters(parts, params, direction_key, bundle_key)
    parts.append(' GROUP BY s.id')
    if metric == 'best_rated':
        parts.append(' HAVING COUNT(i.rating)>=?')
        params.append(RATING_MINIMUMS[scope])
    parts.append(' ORDER BY value DESC,n DESC,s.title,s.id LIMIT ?')
    params.append(top_n)
    # Course: A07 – only predefined SQL pieces are joined; every input is a bound parameter.
    return pd.read_sql(''.join(parts), connection, index_col=['id'], params=tuple(params))


def _append_filters(parts, params, direction_key, bundle_key):
    """Append only fixed filter clauses and keep potentially untrusted values in parameters."""
    for kind, value in (('direction', direction_key), ('bundle', bundle_key)):
        if value is not None:
            if not isinstance(value, str):
                raise ValueError('Category filters must be text keys.')
            parts.append(FILTER_SQL[kind])
            params.append(value)


def category_overview(connection, user_id):
    """Return current confirmed plans and average ratings for every direction, including zeros.

    :param connection: open SQLite connection
    :param user_id: positive local user ID
    :return: direction DataFrame with You/All users counts and nullable rating averages
    """
    if type(user_id) is not int or user_id <= 0:
        raise ValueError('Category overview requires a positive user ID.')
    # SPEC glossary: confirmed is a current plan; past attendance is counted in Most popular.
    query = '''SELECT d.id,d.key AS direction_key,d.name AS direction_name,
        COUNT(CASE WHEN i.user_id=? AND i.status='confirmed' THEN i.id END) AS you_confirmed,
        COUNT(CASE WHEN i.status='confirmed' THEN i.id END) AS all_confirmed,
        AVG(CASE WHEN i.user_id=? THEN i.rating END) AS you_avg_rating,
        AVG(i.rating) AS all_avg_rating
        FROM directions d LEFT JOIN bundles b ON b.direction_id=d.id
        LEFT JOIN series s ON s.bundle_id=b.id LEFT JOIN events e ON e.series_id=s.id
        LEFT JOIN interactions i ON i.event_id=e.id GROUP BY d.id ORDER BY d.sort_order'''
    return pd.read_sql(query, connection, index_col=['id'], params=(user_id, user_id))


def plot_ranking(ranking_df, title):
    """Return a horizontal ranking Figure with direction colours and numeric bar labels."""
    # Course: A09 – the DataFrame order already contains the SQL ranking; invert the y-axis.
    fig, axis = plt.subplots(figsize=config.CHART_SIZE, layout='constrained')
    positions = range(len(ranking_df))
    labels = [textwrap.fill(title, config.CHART_LABEL_WIDTH) for title in ranking_df['title']]
    colors = [config.DIRECTION_COLORS[key]['hex'] for key in ranking_df['direction_key']]
    bars = axis.barh(positions, ranking_df['value'], color=colors)
    axis.set_yticks(list(positions), labels)
    axis.invert_yaxis()
    axis.bar_label(bars, fmt='%.2f', padding=config.CHART_LABEL_PADDING)
    axis.set_title(title)
    axis.set_xlabel('Ranking value (counts, or stars for Best rated)')
    axis.margins(x=config.CHART_VALUE_MARGIN)
    # Closing detaches pyplot's global manager; callers can still render/save the Figure.
    plt.close(fig)
    return fig


def plot_category_overview(overview_df):
    """Return grouped confirmed-plan bars; averages remain in the accompanying table."""
    fig, axis = plt.subplots(figsize=config.CHART_SIZE, layout='constrained')
    width = config.CHART_BAR_WIDTH
    positions = range(len(overview_df))
    for offset, column, label, color in (
            (-width / 2, 'you_confirmed', 'You', config.CHART_PRIMARY_COLOR),
            (width / 2, 'all_confirmed', 'All users', config.CHART_SECONDARY_COLOR)):
        bars = axis.bar([position + offset for position in positions], overview_df[column],
                        width, label=label, color=color)
        axis.bar_label(bars, padding=config.CHART_LABEL_PADDING)
    axis.set_xticks(list(positions), overview_df['direction_name'])
    axis.set_ylabel('Current confirmed plans')
    axis.set_title('Category overview')
    axis.margins(y=config.CHART_VALUE_MARGIN)
    axis.legend()
    plt.close(fig)
    return fig
